import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom'; // <-- import useNavigate
import Footer from '../../Components/Footer/Footer'
import Header from '../../Components/Header/Header'
import './SignUp.css';
import eyeIcon from '../../Assets/eye.png';
import gmailIcon from '../../Assets/gmail.png';
import googleIcon from '../../Assets/google.png';
import signupImage from '../Assets/sigupImage.png';

function SignUp() {
  const [formData, setFormData] = useState({ email: '', password: '' });
  const [showPassword, setShowPassword] = useState(false);
  const [errors, setErrors] = useState({});
  const navigate = useNavigate();  // <-- initialize navigate hook

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const validate = () => {
    const tempErrors = {};

    if (!formData.email) {
      tempErrors.email = 'Email is required';
    } else {
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!emailRegex.test(formData.email)) {
        tempErrors.email = 'Invalid email format';
      }
    }

    if (!formData.password) {
      tempErrors.password = 'Password is required';
    } else {
      const passwordRegex =
        /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[\W_]).{8,}$/;
      if (!passwordRegex.test(formData.password)) {
        tempErrors.password =
          'Password must be at least 8 characters long and include uppercase, lowercase, number, and special character';
      }
    }

    setErrors(tempErrors);
    return Object.keys(tempErrors).length === 0;
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (validate()) {
      alert('Signed Up Successfully!');
      navigate('/signin'); // <-- redirect to SignIn.jsx route after success
    }
  };

  return (
    <div>
      <Header />

      <div className="signup-wrapper">
        <div className="signup-left">
          <form onSubmit={handleSubmit} className="signup-form">
            <h1 className="form-title">Sign Up</h1>
            <p className="form-subtitle"><strong>Where Style Meets Confidence.</strong></p>

            <label className="form-label">Email Address</label>
            <input
              type="email"
              name="email"
              value={formData.email}
              onChange={handleChange}
              className="form-input"
              autoComplete="email"
            />
            {errors.email && <p className="error-msg">{errors.email}</p>}

            <label className="form-label">Your Password</label>
            <div className="password-input-wrapper">
              <input
                type={showPassword ? 'text' : 'password'}
                name="password"
                value={formData.password}
                onChange={handleChange}
                className="form-input"
                autoComplete="new-password"
              />
              <img
                src={eyeIcon}
                alt="toggle visibility"
                className="eye-icon"
                onClick={() => setShowPassword(!showPassword)}
              />
            </div>
            {errors.password && <p className="error-msg">{errors.password}</p>}

            <button type="submit" className="submit-btn">Sign Up</button>

            <p className="continue-text">or continue with</p>

            <div className="social-icons">
              <img src={gmailIcon} alt="Gmail" />
              <img src={googleIcon} alt="Google" />
            </div>

            <p className="signup-text">
              <span className="no-account">Already have an account? </span>
              <span className="signup-link" onClick={() => navigate('/signin')}>Sign In</span>
            </p>
          </form>
        </div>

        <div className="signup-right">
          <div className="half-bg"></div>
          <img src={signupImage} alt="Illustration" className="signup-img" />
        </div>
      </div>

      <Footer />
    </div>
  );
}

export default SignUp;
